import type { LearnLocale } from "@/lib/learn/i18n";
import type { Site } from "@/lib/learn/types";
import type { ContentOverlay } from "./overlay";
import manifest from "./asset-manifest.json";

/**
 * Presentation overlays live OUTSIDE the Worker code bundle, as versioned static assets generated by
 * scripts/learn/build-content-assets.mjs: /learn-content/<version>/<site>/<locale>.json. The committed manifest (this import, a few KB)
 * pins the version, the canonical-content hash and every file's checksum, so a request can only ever read the overlay that was built
 * for the canonical items it is about to localise.
 *
 *   next start / dev / tests: read from public/ on disk.
 *   Cloudflare Worker: read through the ASSETS binding (the /learn-content/* path is worker-first and refused to browsers, so hints and
 *                      explanations are no more public than before - they are still released by the API only when requested).
 * Either way the bytes must match the manifest's sha256.
 * A missing or mismatching asset is an error (learn_content_asset_*): never another locale, never a silent fallback.
 */
type Manifest = { version: string; sites: Record<string, { canonicalSha: string; presentationLocale: string; locales: Record<string, { sha256: string; bytes: number; questions: number }> }> };
const M = manifest as Manifest;
export const CONTENT_VERSION = M.version;
export const contentAssetPath = (site: Site, locale: LearnLocale) => `/learn-content/${M.version}/${site}/${locale}.json`;

export class ContentAssetError extends Error {}

async function readAsset(assetPath: string): Promise<string> {
  // next start / dev / tests: the generated file on disk (a Worker has no real filesystem, so this read fails there)
  try {
    const fs = await import("node:fs/promises");
    const path = await import("node:path");
    return await fs.readFile(path.join(process.cwd(), "public", assetPath), "utf8");
  } catch {
    // not on disk here: Cloudflare Worker - read through the ASSETS binding below
  }
  let assets: { fetch(input: Request | string): Promise<Response> } | undefined;
  try {
    const { getCloudflareContext } = await import("@opennextjs/cloudflare");
    const { env } = await getCloudflareContext({ async: true });
    assets = (env as { ASSETS?: { fetch(input: Request | string): Promise<Response> } }).ASSETS;
  } catch {
    assets = undefined;
  }
  if (!assets) throw new ContentAssetError(`learn_content_asset_missing:${assetPath} (run node scripts/learn/build-content-assets.mjs)`);
  const res = await assets.fetch(new Request(`https://assets.invalid${assetPath}`));
  if (!res.ok) throw new ContentAssetError(`learn_content_asset_missing:${assetPath}:${res.status}`);
  return await res.text();
}

async function sha256(text: string): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
  return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

const cache = new Map<string, Promise<ContentOverlay>>();
/** The overlay of one (site, locale), or null for the site's presentation locale (the canonical bundle itself). */
export function loadOverlayAsset(site: Site, locale: LearnLocale): Promise<ContentOverlay> | null {
  const siteEntry = M.sites[site];
  if (!siteEntry) throw new ContentAssetError(`learn_content_unknown_site:${site}`);
  if (locale === siteEntry.presentationLocale) return null;
  const entry = siteEntry.locales[locale];
  if (!entry) throw new ContentAssetError(`learn_content_asset_not_in_manifest:${site}/${locale}`);
  const key = `${site}/${locale}`;
  let hit = cache.get(key);
  if (!hit) {
    hit = readAsset(contentAssetPath(site, locale)).then(async (text) => {
      // byte-exact: the file must be the one the committed manifest was built with (no stale or partial asset is ever used)
      if ((await sha256(text)) !== entry.sha256) throw new ContentAssetError(`learn_content_asset_checksum:${key}`);
      const data = JSON.parse(text) as { site: string; locale: string; canonicalSha: string; overlay: ContentOverlay };
      if (data.site !== site || data.locale !== locale || data.canonicalSha !== siteEntry.canonicalSha) {
        throw new ContentAssetError(`learn_content_asset_mismatch:${key}`);
      }
      return data.overlay;
    });
    hit.catch(() => cache.delete(key)); // a failed read is retried on the next request, never cached
    cache.set(key, hit);
  }
  return hit;
}
